CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TYPE public.app_role AS ENUM ('admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO anon,authenticated,service_role;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.movies (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, title text NOT NULL CHECK(length(trim(title)) BETWEEN 1 AND 150), genres text[] NOT NULL CHECK(cardinality(genres) BETWEEN 1 AND 8), synopsis text NOT NULL CHECK(length(trim(synopsis)) BETWEEN 1 AND 5000), runtime integer NOT NULL CHECK(runtime BETWEEN 1 AND 600), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','scheduled','published')), poster_path text NOT NULL, tagline text NOT NULL DEFAULT '', language text NOT NULL DEFAULT 'English', rating text NOT NULL DEFAULT 'PG', score numeric NOT NULL DEFAULT 0, moods text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.movies TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.movies TO authenticated; GRANT ALL ON public.movies TO service_role;
ALTER TABLE public.movies ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_movies ON public.movies FOR SELECT TO anon,authenticated USING(status IN ('scheduled','published'));
CREATE POLICY admin_movies ON public.movies FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.screens (id text PRIMARY KEY, cinema_id text NOT NULL CHECK(cinema_id IN ('civil-mall','labim','bhaktapur','pokhara')), name text NOT NULL);
GRANT SELECT ON public.screens TO anon,authenticated; GRANT ALL ON public.screens TO service_role;
ALTER TABLE public.screens ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_screens ON public.screens FOR SELECT TO anon,authenticated USING(true);
CREATE TABLE public.screenings (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, movie_id text NOT NULL REFERENCES public.movies(id) ON DELETE RESTRICT, screen_id text NOT NULL REFERENCES public.screens(id), starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, buffer_minutes integer NOT NULL DEFAULT 15 CHECK(buffer_minutes BETWEEN 0 AND 120), occupied_until timestamptz NOT NULL, format text NOT NULL DEFAULT '2D' CHECK(format IN ('2D','3D','IMAX')), status text NOT NULL DEFAULT 'scheduled' CHECK(status IN ('scheduled','cancelled')), created_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_at>starts_at), EXCLUDE USING gist(screen_id WITH =, tstzrange(starts_at,occupied_until,'[)') WITH &&) WHERE(status='scheduled'));
GRANT SELECT ON public.screenings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.screenings TO authenticated; GRANT ALL ON public.screenings TO service_role;
ALTER TABLE public.screenings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_screenings ON public.screenings FOR SELECT TO anon,authenticated USING(status='scheduled' AND EXISTS(SELECT 1 FROM public.movies m WHERE m.id=movie_id AND m.status='published'));
CREATE POLICY admin_screenings ON public.screenings FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), ref text UNIQUE NOT NULL, screening_id text NOT NULL REFERENCES public.screenings(id), owner_id uuid, capability uuid NOT NULL UNIQUE, seats text[] NOT NULL, total integer NOT NULL, customer_name text NOT NULL, email text NOT NULL, phone text NOT NULL, payment text NOT NULL, status text NOT NULL DEFAULT 'Confirmed' CHECK(status IN ('Confirmed','Cancelled')), movie_title text NOT NULL, poster_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bookings TO authenticated; GRANT ALL ON public.bookings TO service_role;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_bookings ON public.bookings FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.validate_screening() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r integer; BEGIN
 IF TG_OP='DELETE' THEN IF EXISTS(SELECT 1 FROM bookings WHERE screening_id=OLD.id AND status='Confirmed') THEN RAISE EXCEPTION 'Confirmed bookings exist. This screening cannot be deleted.'; END IF; RETURN OLD; END IF;
 IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM bookings WHERE screening_id=OLD.id AND status='Confirmed') AND (NEW.movie_id,NEW.screen_id,NEW.starts_at,NEW.status,NEW.format,NEW.buffer_minutes) IS DISTINCT FROM (OLD.movie_id,OLD.screen_id,OLD.starts_at,OLD.status,OLD.format,OLD.buffer_minutes) THEN RAISE EXCEPTION 'Confirmed bookings exist. Cancel the tickets before changing this screening.'; END IF;
 IF NEW.status='scheduled' AND (TG_OP='INSERT' OR NEW.starts_at IS DISTINCT FROM OLD.starts_at) AND NEW.starts_at<=now() THEN RAISE EXCEPTION 'Choose a future start time.'; END IF;
 SELECT runtime INTO r FROM movies WHERE id=NEW.movie_id FOR SHARE;
 NEW.ends_at:=NEW.starts_at+make_interval(mins=>r); NEW.occupied_until:=NEW.ends_at+make_interval(mins=>NEW.buffer_minutes); RETURN NEW;
 END $$;
CREATE TRIGGER screening_validation BEFORE INSERT OR UPDATE OR DELETE ON public.screenings FOR EACH ROW EXECUTE FUNCTION public.validate_screening();
CREATE FUNCTION public.protect_movie() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF TG_OP='DELETE' THEN IF EXISTS(SELECT 1 FROM screenings WHERE movie_id=OLD.id) THEN RAISE EXCEPTION 'Movies with screenings cannot be deleted. Unpublish instead.'; END IF; RETURN OLD; END IF;
 IF (NEW.runtime IS DISTINCT FROM OLD.runtime OR NEW.status IS DISTINCT FROM OLD.status) AND EXISTS(SELECT 1 FROM bookings b JOIN screenings s ON s.id=b.screening_id WHERE s.movie_id=OLD.id AND b.status='Confirmed' AND s.starts_at>now()) THEN RAISE EXCEPTION 'Upcoming confirmed bookings exist. Runtime and publication status cannot change.'; END IF;
 IF NEW.runtime IS DISTINCT FROM OLD.runtime THEN UPDATE screenings SET ends_at=starts_at+make_interval(mins=>NEW.runtime),occupied_until=starts_at+make_interval(mins=>NEW.runtime+buffer_minutes) WHERE movie_id=OLD.id AND status='scheduled'; END IF; RETURN NEW;
 END $$;
CREATE TRIGGER movie_protection BEFORE UPDATE OR DELETE ON public.movies FOR EACH ROW EXECUTE FUNCTION public.protect_movie();
CREATE FUNCTION public.available_seats(show_id text) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(array_agg(seat),'{}') FROM bookings b CROSS JOIN unnest(b.seats) seat WHERE b.screening_id=show_id AND b.status='Confirmed' $$;
GRANT EXECUTE ON FUNCTION public.available_seats(text) TO anon,authenticated;
CREATE FUNCTION public.reserve_tickets(show_id text, selected_seats text[], customer_name text, customer_email text, customer_phone text, payment_method text, booking_capability uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s screenings; m movies; amount integer:=0; seat text; b bookings; BEGIN
 SELECT * INTO s FROM screenings WHERE id=show_id FOR UPDATE; IF NOT FOUND OR s.status<>'scheduled' OR s.starts_at<=now() THEN RAISE EXCEPTION 'This screening is no longer available.'; END IF;
 SELECT * INTO m FROM movies WHERE id=s.movie_id FOR SHARE; IF m.status<>'published' THEN RAISE EXCEPTION 'This movie is not available for booking.'; END IF;
 IF cardinality(selected_seats) NOT BETWEEN 1 AND 10 OR cardinality(selected_seats)<>(SELECT count(DISTINCT x) FROM unnest(selected_seats) x) THEN RAISE EXCEPTION 'Choose 1 to 10 different seats.'; END IF;
 IF length(trim(customer_name)) NOT BETWEEN 2 AND 100 OR length(customer_email)>255 OR customer_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR customer_phone !~ '^9[78][0-9]{8}$' OR payment_method NOT IN ('eSewa','Khalti','Card') THEN RAISE EXCEPTION 'Enter valid contact details.'; END IF;
 IF EXISTS(SELECT 1 FROM bookings WHERE screening_id=show_id AND status='Confirmed' AND seats && selected_seats) THEN RAISE EXCEPTION 'Some seats were just taken. Please reselect.'; END IF;
 FOREACH seat IN ARRAY selected_seats LOOP IF seat !~ '^[A-J]([1-9]|1[0-4])$' THEN RAISE EXCEPTION 'Invalid seat.'; END IF; amount:=amount+CASE WHEN left(seat,1) IN ('I','J') THEN 600 WHEN left(seat,1) IN ('G','H') THEN 450 ELSE 300 END+CASE s.format WHEN '3D' THEN 100 WHEN 'IMAX' THEN 200 ELSE 0 END+25; END LOOP;
 INSERT INTO bookings(ref,screening_id,owner_id,capability,seats,total,customer_name,email,phone,payment,movie_title,poster_path) VALUES('RYX-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,10)),show_id,auth.uid(),booking_capability,selected_seats,amount,trim(customer_name),customer_email,customer_phone,payment_method,m.title,m.poster_path) RETURNING * INTO b;
 RETURN to_jsonb(b); END $$;
REVOKE ALL ON FUNCTION public.reserve_tickets(text,text[],text,text,text,text,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.reserve_tickets(text,text[],text,text,text,text,uuid) TO anon,authenticated;
CREATE FUNCTION public.cancel_ticket(booking_capability uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b bookings; BEGIN SELECT * INTO b FROM bookings WHERE capability=booking_capability FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Booking not found.'; END IF; IF (SELECT starts_at FROM screenings WHERE id=b.screening_id)<=now() THEN RAISE EXCEPTION 'Past screenings cannot be cancelled.'; END IF; UPDATE bookings SET status='Cancelled' WHERE id=b.id; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.cancel_ticket(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.cancel_ticket(uuid) TO anon,authenticated;
CREATE POLICY poster_admin_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='movie-posters' AND public.has_role(auth.uid(),'admin') AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY poster_admin_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='movie-posters' AND public.has_role(auth.uid(),'admin'));
CREATE POLICY poster_public_read ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='movie-posters' AND EXISTS(SELECT 1 FROM public.movies WHERE poster_path=name AND status IN ('scheduled','published')));
CREATE POLICY poster_admin_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='movie-posters' AND public.has_role(auth.uid(),'admin'));
CREATE INDEX screening_movie_date ON public.screenings(movie_id,starts_at); CREATE INDEX bookings_screening ON public.bookings(screening_id);